  .setName('bannir')
  .setDescription('Bannit un utilisateur du serveur.')
  .addUserOption(option =>
    option
      .setName('utilisateur')
      .setDescription('L\'utilisateur à bannir.')
      .setRequired(true),
  )
  .toJSON();

// Écoutez les événements de la commande "bannir"
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'bannir') {
    // Vérifiez si l'interaction est une commande à l'aide de boutons
    if (!interaction.isSlash()) return;

    const user = interaction.options.getUser('utilisateur');

    // Vérifiez si l'interaction est une commande valide
    if (!interaction.inGuild()) {
      return interaction.reply({
        content: 'Cette commande est disponible uniquement dans un serveur Discord.',
        ephemeral: true,
      });
    }

    // Vérifiez si l'utilisateur cible est un membre du serveur
    if (!user.guild.members.me.permissions.has('BAN_MEMBERS')) {
