Voici un exemple de programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string motSpecifique; // Mot à rechercher dans le fichier
    int count = 0; // Compteur d'occurrences du mot

    // Demander l'entrée du mot à rechercher
    cout << "Entrez le mot à rechercher : ";
    cin >> motSpecifique;

    // Ouvrir le fichier pour lecture
    string nomFichier;
    cout << "Entrez le nom du fichier : ";
    cin >> nomFichier;
    ifstream fichier(nomFichier);

    // Vérifier si le fichier a bien été ouvert
    if (!fichier.is_open()) {
        cerr << "Impossible d'ouvrir le fichier " << nomFichier << endl;
        return 1;
    }

    // Lire le contenu du fichier ligne par ligne
    string ligne;
    while (getline(fichier, ligne)) {

        // Convertir la ligne en majuscules pour une comparaison case-insensitive
        transform(ligne.begin(), ligne.end(), ligne.begin(), ::toupper);

        // Rechercher le mot dans la ligne
        size_t position = search(ligne.begin(), ligne.end(), motSpecifique.begin(), motSpecifique.end(), ::toupper);
        while (position != string::npos) {
            count++; // Incrémenter le compteur d'occurrences
            position = search(position + 1, ligne.end(), motSpecifique.begin(), motSpecifique.end(), ::toupper);
        }
    }

    // Fermer le fichier
    fichier.close();

    // Afficher le résultat
    cout << "Le mot \"" << motSpecifique << "\" apparait " << count << " fois dans le fichier " << nomFichier << endl;

    return 0;
}
