Voici une implémentation en JavaScript pour trouver les éléments communs à deux tableaux sans utiliser de structures de données supplémentaires :

```javascript
function findCommonElements(arr1, arr2) {
  // On trie les deux tableaux
  arr1.sort((a, b) => a - b);
  arr2.sort((a, b) => a - b);

  let i = 0; // Index du premier tableau
  let j = 0; // Index du deuxième tableau

  const commonElements = [];

  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] === arr2[j]) {
      commonElements.push(arr1[i]);
      i++; // On avance dans le premier tableau
      j++; // On avance dans le deuxième tableau
    } else if (arr1[i] < arr2[j]) {
      i++; // On avance dans le premier tableau
    } else {
      j++; // On avance dans le deuxième tableau
    }
  }

  return commonElements;
}
